let clientSettingsSnapshot = "defaults"
let clientSettingsHydrationGeneration = 0

function readStoredSettings(): string | null {
  return typeof window === "undefined" ? null : (window.localStorage?.getItem("settings") ?? clientSettingsSnapshot)
}

export function hydrateClientSettings(): string {
  const generation = clientSettingsHydrationGeneration
  const stored = readStoredSettings()
  if (stored !== null && generation === clientSettingsHydrationGeneration) clientSettingsSnapshot = stored
  return clientSettingsSnapshot
}

export function resetClientSettingsForTests(): void {
  clientSettingsSnapshot = "defaults"
  clientSettingsHydrationGeneration += 1
}

export function getClientSettings(): string {
  return clientSettingsSnapshot
}
